class_name RoverSite

# rover_site.gd
# Abandoned Martian rover half-sunk into the regolith with tire tracks
# and scattered rock debris as scenic decoration.

func _ready() -> void:
	_spawn_small_rocks()

func _spawn_small_rocks() -> void:
	var rng = RandomNumberGenerator.new()
	rng.seed = 4242

	var mat = StandardMaterial3D.new()
	mat.albedo_color = Color(0.72, 0.30, 0.16)
	mat.roughness = 0.95

	# Scatter 20 small rocks within 2.5m to 7.0m of the rover
	var rocks_root = Node3D.new()
	rocks_root.name = "ScatteredRocks"
	add_child(rocks_root)

	for i in range(20):
		var mi = MeshInstance3D.new()
		var sm = BoxMesh.new()
		var s_size = rng.randf_range(0.18, 0.42)
		sm.size = Vector3(s_size, s_size * 0.7, s_size * 1.1)
		mi.mesh = sm
		mi.material_override = mat

		var r_angle = rng.randf() * TAU
		var r_dist = rng.randf_range(2.6, 6.8)
		mi.position = Vector3(cos(r_angle) * r_dist, 0.05, sin(r_angle) * r_dist)
		mi.rotation = Vector3(rng.randf() * 0.8, rng.randf() * TAU, rng.randf() * 0.8)
		rocks_root.add_child(mi)
"

"extends Area3D
class_name WaterIcePickup

# water_ice_pickup.gd
# Collectable water ice crystal on the water ice patch.
# Press E to collect, adds to inventory, prints count after each pickup.

@export var sample_id: int = 1

@onready var prompt_label: Label3D = $PromptLabel
@onready var ice_mesh: MeshInstance3D = $IceMesh

var is_player_nearby: bool = false
var is_collected: bool = false

func _ready() -> void:
	body_entered.connect(_on_body_entered)
	body_exited.connect(_on_body_exited)

func _unhandled_input(event: InputEvent) -> void:
	if not is_player_nearby or is_collected:
		return
	if event.is_action_pressed("interact") or (event is InputEventKey and event.pressed and not event.echo and event.physical_keycode == KEY_E):
		collect()
		get_viewport().set_input_as_handled()

func _on_body_entered(body: Node3D) -> void:
	if body.is_in_group("player") or body.name == "Player":
		is_player_nearby = true
		_update_prompt()

func _on_body_exited(body: Node3D) -> void:
	if body.is_in_group("player") or body.name == "Player":
		is_player_nearby = false
		_update_prompt()

func _update_prompt() -> void:
	var hud = _get_hud()
	if is_player_nearby and not is_collected:
		if prompt_label:
			prompt_label.visible = true
		if hud and hud.has_method("show_interaction_prompt"):
			hud.show_interaction_prompt("Take Water Ice")
	else:
		if prompt_label:
			prompt_label.visible = false
		if hud and hud.has_method("clear_interaction_prompt"):
			hud.clear_interaction_prompt()

func collect() -> void:
	if is_collected:
		return

	is_collected = true
	var gm = get_node_or_null("/root/GameManager")
	var count = 1
	if gm:
		gm.add_water_ice(1)
		count = gm.water_ice

	print("[WATER ICE PICKUP] Water ice #%d collected! Count in inventory: %d" % [sample_id, count])

	var col = get_node_or_null("CollisionShape3D") as CollisionShape3D
	if col:
		col.set_deferred("disabled", true)

