	var scn = load("res://Scenes/player/player.tscn")
	var player = scn.instantiate()
	root.add_child(player)

	var astro_root = player.get_node("VisualMesh/Astronaut")
	var t = player.default_astro_transform.rotated_local(Vector3.RIGHT, deg_to_rad(90.0))
	t.origin = Vector3.ZERO
	astro_root.transform = t

	# Find lowest point among all bones and mesh vertices
	var sk = player.find_child("Skeleton3D", true, false) as Skeleton3D
	var min_y_bone = 1e9
	var lowest_bone_name = ""
	for b in range(sk.get_bone_count()):
		var b_pose = sk.get_bone_global_pose(b)
		var b_world = astro_root.transform * b_pose.origin
		if b_world.y < min_y_bone:
			min_y_bone = b_world.y
			lowest_bone_name = sk.get_bone_name(b)
	print("Lowest bone when prone: ", lowest_bone_name, " Y: ", min_y_bone)

	# Also check mesh aabbs transformed by astro_root
	var meshes = player.find_children("*", "MeshInstance3D", true, false)
	var min_y_mesh = 1e9
	for m in meshes:
		var mi = m as MeshInstance3D
		if not mi.mesh: continue
		var aabb = mi.get_aabb()
		for xi in [0, 1]:
			for yi in [0, 1]:
				for zi in [0, 1]:
					var pt = aabb.position + aabb.size * Vector3(xi, yi, zi)
					var p_local = astro_root.transform * pt
					if p_local.y < min_y_mesh:
						min_y_mesh = p_local.y
	print("Lowest mesh AABB corner when prone (t.origin=0): ", min_y_mesh)
	quit()
"

